class DSU {
    int[] p, r;
    DSU(int n){ p=new int[n]; r=new int[n]; for(int i=0;i<n;i++) p[i]=i; }
    int find(int x){ return p[x]==x?x:(p[x]=find(p[x])); }
    boolean unite(int a,int b){ a=find(a); b=find(b); if(a==b) return false; if(r[a]<r[b]){int t=a;a=b;b=t;} p[b]=a; if(r[a]==r[b]) r[a]++; return true; }
}

// edges: List of int[]{u,v,w}
public int kruskalMST(int n, List<int[]> edges){
    edges.sort(Comparator.comparingInt(e->e[2]));
    DSU dsu=new DSU(n); int total=0,cnt=0;
    for(int[] e:edges){ if(dsu.unite(e[0],e[1])){ total+=e[2]; if(++cnt==n-1) break; } }
    return cnt==n-1? total: -1;
}

