// edges: List of int[]{u,v,w}
public Object[] bellmanFord(int n, List<int[]> edges, int src){
    long INF = Long.MAX_VALUE/4;
    long[] dist = new long[n];
    Arrays.fill(dist, INF); dist[src]=0;
    for(int i=1;i<=n-1;i++){
        boolean updated=false;
        for(int[] e: edges){ int u=e[0], v=e[1], w=e[2];
            if(dist[u]!=INF && dist[u]+w<dist[v]){ dist[v]=dist[u]+w; updated=true; }
        }
        if(!updated) break;
    }
    for(int[] e: edges){ int u=e[0], v=e[1], w=e[2];
        if(dist[u]!=INF && dist[u]+w<dist[v]) return new Object[]{dist, true};
    }
    return new Object[]{dist, false};
}

