public List<Integer> kmpSearch(String text, String pat){
    int n=text.length(), m=pat.length();
    if(m==0) return Collections.emptyList();
    int[] lps = new int[m];
    for(int i=1, len=0; i<m; ){
        if(pat.charAt(i)==pat.charAt(len)) lps[i++]=++len;
        else if(len>0) len=lps[len-1]; else lps[i++]=0;
    }
    List<Integer> res=new ArrayList<>();
    for(int i=0,j=0;i<n;){
        if(text.charAt(i)==pat.charAt(j)){ i++; j++; if(j==m){ res.add(i-m); j=lps[j-1]; } }
        else if(j>0) j=lps[j-1]; else i++;
    }
    return res;
}

