public List<Integer> rabinKarp(String text, String pat){
    int n=text.length(), m=pat.length();
    if(m==0 || m>n) return Collections.emptyList();
    long B=131, MOD=1_000_000_007L;
    long powB=1; for(int i=0;i<m-1;i++) powB = (powB*B)%MOD;
    long hpat=0, hwin=0;
    for(int i=0;i<m;i++){ hpat=(hpat*B+pat.charAt(i))%MOD; hwin=(hwin*B+text.charAt(i))%MOD; }
    List<Integer> out=new ArrayList<>();
    for(int i=0;i<=n-m;i++){
        if(hpat==hwin && text.substring(i,i+m).equals(pat)) out.add(i);
        if(i<n-m){ hwin = ( (hwin - text.charAt(i)*powB)%MOD + MOD )%MOD; hwin = (hwin*B + text.charAt(i+m))%MOD; }
    }
    return out;
}

