public int[] sieveIsPrime(int n){
    int[] is = new int[n+1]; Arrays.fill(is, 1);
    if(n>=0) is[0]=0; if(n>=1) is[1]=0;
    for(int p=2; p*p<=n; p++) if(is[p]==1){
        for(long x=1L*p*p; x<=n; x+=p) is[(int)x]=0;
    }
    return is;
}

