public int lisLength(int[] a){
    int n=a.length;
    int[] tails=new int[n]; int len=0;
    for(int x: a){
        int i=Arrays.binarySearch(tails,0,len,x);
        if(i<0) i=-(i+1);
        tails[i]=x;
        if(i==len) len++;
    }
    return len;
}

public int quickselect(int[] a, int k){ // k: 1-based
    int l=0, r=a.length-1; k--;
    while(l<=r){
        int pivot=a[r], i=l;
        for(int j=l;j<r;j++){ if(a[j]<=pivot){ int t=a[i];a[i]=a[j];a[j]=t; i++; } }
        int t=a[i];a[i]=a[r];a[r]=t;
        if(i==k) return a[i]; else if(i>k) r=i-1; else l=i+1;
    }
    throw new IllegalArgumentException("k out of range");
}
